151	// 正常写法差异不能误判为损坏：合法范围内 1 与 1.000、0 与 0.000、-1 与
152	// -1.000 是相同数量，不能只因末尾的零不同拒绝读取。台账应正常打开，
153	// 重放返回保存的写法，查询返回规范化写法。
154	func TestCloseResultAtLimitAcceptsFormatVariants(t *testing.T) {
155		dir := t.TempDir()
156		_, good := setupLimitCloseLedger(t, dir, false)
157	
158		bad := corruptCloseRequestResult(t, good, func() json.RawMessage {
159			return mutatedCloseView(t, good, func(v *BatchView) {
160				v.Materials[0].ActualGrams = "0.000"      // 与 0 是同一数量
161				v.Materials[1].RequiredGrams = "1.000"    // 与 1 是同一数量
162				v.Materials[1].ActualGrams = "0.000"      // 与 0 是同一数量
163				v.Materials[1].DifferenceGrams = "-1.000" // 与 -1 是同一数量
164			})
165		})
166		if err := os.WriteFile(filepath.Join(dir, stateFileName), bad, 0o644); err != nil {
167			t.Fatal(err)
168		}
169	
170		s, err := Open(dir)
171		if err != nil {
172			t.Fatalf("末尾零的写法差异不应判为损坏: %v", err)
173		}
174		defer s.Close()
175	
176		// 重放取回保存的结果原文：保持 0.000、1.000、-1.000 的写法。
177		replay, err := s.CloseBatch("close-b1", "B1")
178		if err != nil {
179			t.Fatalf("重放关闭请求应成功: %v", err)
180		}
181		mats := materialsMap(replay)
182		if mats["M1"].ActualGrams != "0.000" || mats["M2"].RequiredGrams != "1.000" ||
183			mats["M2"].ActualGrams != "0.000" || mats["M2"].DifferenceGrams != "-1.000" {
184			t.Fatalf("重放应返回保存的核对项写法，得到 %+v", replay.Materials)
185		}
186		// 按批次查询得到系统规范化写法的视图，数量与首次关闭一致。
187		checkLimitClosedView(t, mustGetBatch(t, s, "B1"), "0", "-"+limitGrams)
188	}
189	
190	// 保存结果的应投量、实投量或差额只要与配方和实际投料相差 0.001 克，即使
191	// 仍在数量上限内，也必须返回 ErrCorruptData：数量相同与数量不符之间的
192	// 区别必须保住，原始投料完整不能使写错的关闭结果变成合法。错误信息应指出
193	// 关闭请求编号、批次编号及对应物料，原台账内容保持不变。
194	func TestOpenRejectsCloseResultOffByMilliNearLimit(t *testing.T) {
195		cases := []struct {
196			name      string
197			feedMilli bool // 是否使用投过 0.001 克的台账
198			edit      func(v *BatchView)
199			material  string // 错误信息应指出的物料
200		}{
201			{"应投量少 0.001", false, func(v *BatchView) {
202				v.Materials[0].RequiredGrams = "9223372036854775.806"
203			}, "M1"},
204			{"实投量多出 0.001", false, func(v *BatchView) {
205				v.Materials[0].ActualGrams = "0.001"
206			}, "M1"},
207			{"负差额少算 0.001", false, func(v *BatchView) {
208				v.Materials[0].DifferenceGrams = "-9223372036854775.806"
209			}, "M1"},
210			{"负差额被翻成正数", false, func(v *BatchView) {
211				v.Materials[0].DifferenceGrams = limitGrams
212			}, "M1"},
213			{"其他物料差额差 0.001", false, func(v *BatchView) {
214				v.Materials[1].DifferenceGrams = "-1.001"
215			}, "M2"},
216			{"实投丢掉千分之一克", true, func(v *BatchView) {
217				v.Materials[0].ActualGrams = "0"
218			}, "M1"},
219			{"已投 0.001 时差额多算 0.001", true, func(v *BatchView) {
220				v.Materials[0].DifferenceGrams = "-9223372036854775.807"
221			}, "M1"},
222		}
223		for _, tc := range cases {
224			t.Run(tc.name, func(t *testing.T) {
225				dir := t.TempDir()
226				_, good := setupLimitCloseLedger(t, dir, tc.feedMilli)
227				bad := corruptCloseRequestResult(t, good, func() json.RawMessage {
228					return mutatedCloseView(t, good, tc.edit)
229				})
230				if err := os.WriteFile(filepath.Join(dir, stateFileName), bad, 0o644); err != nil {
231					t.Fatal(err)
232				}
233	
234				s, err := Open(dir)
235				if !errors.Is(err, ErrCorruptData) {
236					t.Fatalf("相差 0.001 克的关闭结果应返回 ErrCorruptData，得到 %v", err)
237				}
238				if s != nil {
239					s.Close()
240					t.Fatalf("损坏台账不应返回可用的 Store 对象")
241				}
242				msg := err.Error()
243				for _, want := range []string{"close-b1", "B1", tc.material} {
244					if !strings.Contains(msg, want) {
245						t.Fatalf("错误信息应包含 %q，得到 %v", want, err)
246					}
247				}
248				got, err := os.ReadFile(filepath.Join(dir, stateFileName))
249				if err != nil {
250					t.Fatal(err)
251				}
252				if !bytes.Equal(got, bad) {
253					t.Fatalf("拒绝打开不应改动台账文件")
254				}
255			})
256		}
257	}
258	
259	// 台账正常打开后，保存内容中的关闭结果被改坏（差额差 0.001 克，原始投料
260	// 保持完整）：下一次查询与重放都必须返回 ErrCorruptData——查询不能先用
261	// 正确计算值替换写错的保存结果再返回成功，重放也不能把损坏结果当成第一次
262	// 关闭的结果。被拒绝的访问不改动原台账内容。
263	func TestCloseResultCorruptionNearLimitNotHealedByRecompute(t *testing.T) {
264		dir := t.TempDir()
265		_, good := setupLimitCloseLedger(t, dir, true)
266	
267		s, err := Open(dir)
268		if err != nil {
269			t.Fatalf("Open 失败: %v", err)
270		}
271		defer s.Close()
272	
273		// 打开后把 close-b1 保存结果的差额改坏 0.001 克：原始投料（0.001 克）
274		// 与应投量都保持完整，只有核对差额与配方和实际投料不符。
275		bad := corruptCloseRequestResult(t, good, func() json.RawMessage {
276			return mutatedCloseView(t, good, func(v *BatchView) {
277				v.Materials[0].DifferenceGrams = "-9223372036854775.807"
278			})
279		})
280		if err := os.WriteFile(filepath.Join(dir, stateFileName), bad, 0o644); err != nil {
281			t.Fatal(err)
282		}
283	
284		// 查询该批次：不能用重算的正确差额覆盖写错的保存结果后返回成功。
285		if v, err := s.GetBatch("B1"); !errors.Is(err, ErrCorruptData) {
286			t.Fatalf("查询应返回 ErrCorruptData，得到 %v", err)
287		} else if v != nil {
288			t.Fatalf("被拒绝的查询不应返回部分台账视图: %+v", v)
289		}
290		// 重放关闭请求：不能把损坏的保存结果当成第一次关闭的结果返回。
291		if _, err := s.CloseBatch("close-b1", "B1"); !errors.Is(err, ErrCorruptData) {
292			t.Fatalf("重放损坏的关闭请求应返回 ErrCorruptData，得到 %v", err)
293		}
294	
295		after, err := os.ReadFile(filepath.Join(dir, stateFileName))
296		if err != nil {
297			t.Fatal(err)
298		}
299		if !bytes.Equal(after, bad) {
300			t.Fatalf("被拒绝的访问不应改动台账文件")
301		}
302	}
303	
304	// 负差额的绝对值同样不能超过数量上限：保存成 -9223372036854775.808 克
305	// （或更大的负值）时必须明确拒绝，不能发生数值回绕、截短或舍入后当成合法
306	// 结果读取。应投量超过上限的写法同理。错误信息应指出关闭请求编号、批次
307	// 编号及对应物料的数量问题，原台账内容保持不变。
308	func TestOpenRejectsCloseResultQuantityBeyondLimit(t *testing.T) {
309		cases := []struct {
310			name string
311			edit func(v *BatchView)
312		}{
313			{"负差额绝对值超上限 0.001", func(v *BatchView) {
314				v.Materials[0].DifferenceGrams = "-9223372036854775.808"
315			}},
316			{"负差额整数部分超上限", func(v *BatchView) {
317				v.Materials[0].DifferenceGrams = "-9223372036854776"
318			}},
319			{"负差额远超 int64 不能回绕", func(v *BatchView) {
320				v.Materials[0].DifferenceGrams = "-18446744073709551.615"
321			}},
322			{"应投量超上限 0.001", func(v *BatchView) {
323				v.Materials[0].RequiredGrams = "9223372036854775.808"
324			}},
325		}
326		for _, tc := range cases {
327			t.Run(tc.name, func(t *testing.T) {
328				dir := t.TempDir()
329				_, good := setupLimitCloseLedger(t, dir, false)
330				bad := corruptCloseRequestResult(t, good, func() json.RawMessage {
331					return mutatedCloseView(t, good, tc.edit)
332				})
333				if err := os.WriteFile(filepath.Join(dir, stateFileName), bad, 0o644); err != nil {
334					t.Fatal(err)
335				}
336	
337				s, err := Open(dir)
338				if !errors.Is(err, ErrCorruptData) {
339					t.Fatalf("超出数量上限的关闭结果应返回 ErrCorruptData，得到 %v", err)
340				}
341				if s != nil {
342					s.Close()
343					t.Fatalf("损坏台账不应返回可用的 Store 对象")
344				}
345				msg := err.Error()
346				for _, want := range []string{"close-b1", "B1", "M1"} {
347					if !strings.Contains(msg, want) {
348						t.Fatalf("错误信息应包含 %q，得到 %v", want, err)
349					}
350				}
351				got, err := os.ReadFile(filepath.Join(dir, stateFileName))
352				if err != nil {
353					t.Fatal(err)
354				}
355				if !bytes.Equal(got, bad) {
356					t.Fatalf("拒绝打开不应改动台账文件")
