// 关闭时的完整原始结果。重新打开台账后，重放与查询仍各自反映应有的内容。
func TestCloseBatchResultPreservesFeedingsAndReconciliation(t *testing.T) {
	dir := t.TempDir()
	s, err := Open(dir)
	if err != nil {
		t.Fatalf("Open 失败: %v", err)
